// Test script for video generation API with more realistic audio

const fs = require('fs');
const path = require('path');

// This function encodes a file to a base64 data URL
function fileToDataUrl(filePath, mimeType) {
  const buffer = fs.readFileSync(filePath);
  const base64 = buffer.toString('base64');
  return `data:${mimeType};base64,${base64}`;
}

// Create a 16x16 test image (dimensions must be even for libx264)
function createTestImage() {
  // This is a 16x16 white pixel PNG
  return 'data:image/png;base64,';
}

// More complete silent WAV file with proper duration
function createSilentWav() {
  // 1-second silent WAV file (44.1 kHz, 16-bit, mono) - properly formatted
  const wavBase64 = '';
  return `data:audio/wav;base64,${wavBase64}`;
}

const testVideoGeneration = async () => {
  try {
    // Create test data
    const testImage = createTestImage();
    const testAudio = createSilentWav();
    
    // Prepare request data
    const requestData = {
      images: [testImage, testImage, testImage, testImage], // Four test images
      audioBase64: testAudio,
      hasDynamicTiming: false
    };
    
    console.log('Sending request to generate video...');
    
    // Make the API call
    const response = await fetch('http://localhost:3001/api/video/generate', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(requestData),
    });
    
    const result = await response.json();
    
    console.log('API Response:', response.status);
    console.log('Response data:', result);
    
    if (response.ok) {
      console.log('Video generation successful!');
      console.log('Video URL:', result.videoUrl);
    } else {
      console.error('Video generation failed:', result.error);
      if (result.details) {
        console.error('Error details:', result.details);
      }
      if (result.command) {
        console.error('Command used:', result.command);
      }
    }
  } catch (error) {
    console.error('Error testing video generation API:', error);
  }
};

// Run the test
testVideoGeneration(); 